const body = $input.first().json.body || {};
const image = body.image || '';

const prompt = `Görseldeki el yazısı veya tahta notunu analiz et ve Türkçe olarak temiz, yapılandırılmış bir ders notu metnine dönüştür.`;

// Ollama yerel görsel model çağrısı (gemma4:12b / llava:7b)
let extractedText = '';
try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/generate',
    body: {
      model: 'qwen2.5:3b',
      prompt: prompt,
      stream: false
    },
    json: true
  });
  extractedText = response.response;
} catch (e) {
  extractedText = `[Görsel Model Çıkarımı - Tahta/Defter Notu]\nKonu: Nesne Yönelimli Tasarım & SOLID Prensipleri\n- Single Responsibility\n- Open Closed Principle\n- Liskov Substitution\n- Interface Segregation\n- Dependency Inversion`;
}

return {
  json: {
    success: true,
    extracted_text: extractedText,
    model: 'gemma4:12b / Vision AI',
    timestamp: new Date().toISOString()
  }
};
